package com.emeka45.universaldictionary\n\nimport android.content.Intent\nimport android.media.MediaPlayer\nimport android.os.Bundle\nimport android.webkit.WebResourceRequest\nimport android.webkit.WebView\nimport android.webkit.WebViewClient\nimport androidx.activity.ComponentActivity\nimport androidx.activity.compose.setContent\nimport androidx.compose.foundation.clickable\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.items\nimport androidx.compose.foundation.shape.RoundedCornerShape\nimport androidx.compose.material.icons.Icons\nimport androidx.compose.material.icons.filled.*\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Alignment\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.platform.LocalContext\nimport androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.unit.dp\nimport androidx.compose.ui.viewinterop.AndroidView\nimport com.emeka45.universaldictionary.data.DictionaryRepository\nimport com.emeka45.universaldictionary.model.DictionaryEntry\nimport com.emeka45.universaldictionary.model.SourceDictionary\nimport com.emeka45.universaldictionary.ui.UniversalDictionaryTheme\nimport kotlinx.coroutines.launch\nimport java.util.Locale\n\nclass MainActivity : ComponentActivity() {\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        val incoming = if (intent?.action == Intent.ACTION_PROCESS_TEXT) intent.getCharSequenceExtra(Intent.EXTRA_PROCESS_TEXT)?.toString()?.trim() else null\n        setContent { UniversalDictionaryTheme { DictionaryApp(incoming) } }\n    }\n}\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nprivate fun DictionaryApp(incoming: String?) {\n    val context = LocalContext.current\n    val repository = remember { DictionaryRepository(context.applicationContext) }\n    val scope = rememberCoroutineScope()\n    var tab by remember { mutableIntStateOf(0) }\n    var query by remember { mutableStateOf(incoming.orEmpty()) }\n    var entry by remember { mutableStateOf<DictionaryEntry?>(null) }\n    var loading by remember { mutableStateOf(false) }\n    var error by remember { mutableStateOf<String?>(null) }\n    var suggestions by remember { mutableStateOf(emptyList<String>()) }\n    var saved by remember { mutableStateOf(emptySet<String>()) }\n    var history by remember { mutableStateOf(emptyList<String>()) }\n    var source by remember { mutableStateOf<SourceDictionary?>(null) }\n    suspend fun refresh() { saved = repository.savedWords(); history = repository.history() }\n    fun lookup(word: String = query) {\n        if (word.isBlank()) return\n        scope.launch {\n            loading = true; error = null; suggestions = emptyList()\n            repository.lookup(word).onSuccess { entry = it }.onFailure { error = it.message ?: "Lookup failed." }\n            refresh(); loading = false\n        }\n    }\n    LaunchedEffect(Unit) { refresh(); if (!incoming.isNullOrBlank()) lookup(incoming) }\n    source?.let { InAppDictionary(it, query) { source = null }; return }\n    Scaffold(\n        topBar = { TopAppBar(title = { Column { Text("Universal Dictionary", fontWeight = FontWeight.Bold); Text("Words • Learning • Discovery", style = MaterialTheme.typography.labelSmall) } }) },\n        bottomBar = { NavigationBar {\n            val labels = listOf("Home", "Saved", "History", "Learn")\n            val icons = listOf(Icons.Default.Home, Icons.Default.Bookmark, Icons.Default.History, Icons.Default.School)\n            labels.forEachIndexed { i, label -> NavigationBarItem(selected = tab == i, onClick = { tab = i }, icon = { Icon(icons[i], null) }, label = { Text(label) }) }\n        } }\n    ) { padding ->\n        when (tab) {\n            0 -> HomeScreen(query, { query = it }, suggestions, { suggestions = it }, loading, error, entry, saved, { word -> scope.launch { saved = repository.toggleSaved(word); refresh() } }, { lookup() }, { lookup(it) }, { source = it }, { playAudio(it) }, Modifier.padding(padding), repository)\n            1 -> WordListScreen("Saved words", "Your personal vocabulary collection", saved.toList().sorted(), { lookup(it); tab = 0 }, Modifier.padding(padding))\n            2 -> WordListScreen("Search history", "Your latest lookups", history, { lookup(it); tab = 0 }, Modifier.padding(padding))\n            else -> LearnScreen(saved, history, { lookup(it); tab = 0 }, Modifier.padding(padding))\n        }\n    }\n}\n\n@Composable\nprivate fun HomeScreen(query: String, onQuery: (String) -> Unit, suggestions: List<String>, onSuggestions: (List<String>) -> Unit, loading: Boolean, error: String?, entry: DictionaryEntry?, saved: Set<String>, onSave: (String) -> Unit, onLookup: () -> Unit, onSuggestion: (String) -> Unit, onSource: (SourceDictionary) -> Unit, onSpeak: (String?) -> Unit, modifier: Modifier, repository: DictionaryRepository) {\n    val scope = rememberCoroutineScope()\n    LazyColumn(modifier.fillMaxSize(), contentPadding = PaddingValues(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {\n        item { OutlinedTextField(value = query, onValueChange = { onQuery(it); if (it.trim().length >= 2) scope.launch { onSuggestions(repository.suggestions(it)) } }, modifier = Modifier.fillMaxWidth(), singleLine = true, label = { Text("Search any word") }, leadingIcon = { Icon(Icons.Default.Search, null) }, trailingIcon = { if (loading) CircularProgressIndicator(Modifier.size(22.dp)) else TextButton(onClick = onLookup) { Text("LOOK UP") } }) }\n        if (suggestions.isNotEmpty()) item { Card { Column(Modifier.fillMaxWidth()) { suggestions.forEach { s -> Text(s, Modifier.fillMaxWidth().clickable { onSuggestion(s) }.padding(14.dp)) } } } }\n        if (entry == null && error == null) item { WelcomeCard() }\n        error?.let { message -> item { OutlinedCard { Text(message, Modifier.padding(16.dp), color = MaterialTheme.colorScheme.error) } } }\n        entry?.let { current ->\n            item { EntryCard(current, saved.contains(current.word.lowercase(Locale.US)), { onSave(current.word) }, { onSpeak(current.audioUrl) }) }\n            item { Text("Explore other sources", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold) }\n            items(DictionaryRepository.sources) { s -> SourceCard(s) { onSource(s) } }\n        }\n        if (entry == null) item { Text("Dictionary sources", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold) }\n        if (entry == null) items(DictionaryRepository.sources.take(4)) { s -> SourceCard(s) { onSource(s) } }\n    }\n}\n\n@Composable private fun WelcomeCard() { Card(Modifier.fillMaxWidth(), shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer)) { Column(Modifier.padding(22.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { Text("Your words, everywhere.", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold); Text("Definitions, examples, synonyms, antonyms and pronunciation, plus saved words and source comparison."); Text("Tip: select text in another app and choose Universal Dictionary.", style = MaterialTheme.typography.labelLarge) } } }\n\n@Composable private fun EntryCard(entry: DictionaryEntry, saved: Boolean, onSave: () -> Unit, onSpeak: () -> Unit) {\n    Card(shape = RoundedCornerShape(24.dp)) { Column(Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {\n        Row(verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text(entry.word, style = MaterialTheme.typography.headlineLarge, fontWeight = FontWeight.Bold); entry.phonetic?.let { Text(it) } }; IconButton(onClick = onSpeak, enabled = entry.audioUrl != null) { Icon(Icons.Default.VolumeUp, "Pronunciation") }; IconButton(onClick = onSave) { Icon(if (saved) Icons.Default.Bookmark else Icons.Default.BookmarkBorder, "Save") } }\n        entry.origin?.let { Text("Origin", fontWeight = FontWeight.Bold); Text(it) }\n        entry.definitions.forEachIndexed { index, d -> Column(verticalArrangement = Arrangement.spacedBy(5.dp)) { Text((index + 1).toString() + ". " + d.partOfSpeech, fontWeight = FontWeight.Bold); Text(d.text); d.example?.let { Text("“" + it + "”") }; if (d.synonyms.isNotEmpty()) Text("Synonyms: " + d.synonyms.joinToString(", ")); if (d.antonyms.isNotEmpty()) Text("Antonyms: " + d.antonyms.joinToString(", ")) } }\n        Text("Source: " + entry.source, style = MaterialTheme.typography.labelMedium)\n    } }\n}\n\n@Composable private fun SourceCard(source: SourceDictionary, onClick: () -> Unit) { Card(Modifier.fillMaxWidth().clickable(onClick = onClick)) { Row(Modifier.padding(16.dp), verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Language, null); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text(source.name, fontWeight = FontWeight.Bold); Text(source.description, style = MaterialTheme.typography.bodySmall) }; Text("OPEN", style = MaterialTheme.typography.labelLarge) } } }\n\n@Composable private fun WordListScreen(title: String, subtitle: String, words: List<String>, onWord: (String) -> Unit, modifier: Modifier) { LazyColumn(modifier.fillMaxSize(), contentPadding = PaddingValues(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) { item { Text(title, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold); Text(subtitle) }; if (words.isEmpty()) item { WelcomeCard() }; items(words.distinct()) { word -> ListItem(headlineContent = { Text(word) }, leadingContent = { Icon(Icons.Default.Book, null) }, modifier = Modifier.clickable { onWord(word) }); HorizontalDivider() } } }\n\n@Composable private fun LearnScreen(saved: Set<String>, history: List<String>, onWord: (String) -> Unit, modifier: Modifier) { val pool = (saved + history).toList().distinct(); LazyColumn(modifier.fillMaxSize(), contentPadding = PaddingValues(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { item { Card(shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer)) { Column(Modifier.padding(22.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) { Text("Vocabulary Lab", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold); Text("Review the words you have looked up and turn them into a personal study list."); Text(pool.size.toString() + " words in your learning pool", fontWeight = FontWeight.Bold) } } }; items(pool) { word -> AssistChip(onClick = { onWord(word) }, label = { Text(word) }, leadingIcon = { Icon(Icons.Default.School, null) }) } } }\n\n@Composable private fun InAppDictionary(source: SourceDictionary, word: String, onBack: () -> Unit) { var webView by remember { mutableStateOf<WebView?>(null) }; var canBack by remember { mutableStateOf(false) }; val url = remember(source.name, word) { source.urlFor(word) }; Scaffold(topBar = { TopAppBar(title = { Text(source.name) }, navigationIcon = { IconButton(onClick = { if (canBack) webView?.goBack() else onBack() }) { Icon(Icons.Default.ArrowBack, "Back") } }, actions = { IconButton(onClick = { webView?.reload() }) { Icon(Icons.Default.Refresh, "Refresh") } }) }) { padding -> AndroidView(Modifier.fillMaxSize().padding(padding), factory = { context -> WebView(context).apply { webView = this; settings.javaScriptEnabled = true; settings.domStorageEnabled = true; settings.loadsImagesAutomatically = true; webViewClient = object : WebViewClient() { override fun shouldOverrideUrlLoading(view: WebView?, request: WebResourceRequest?) = false; override fun onPageFinished(view: WebView?, url: String?) { canBack = view?.canGoBack() == true } }; loadUrl(url) } }) } }\n\nprivate fun playAudio(url: String?) { if (url.isNullOrBlank()) return; runCatching { MediaPlayer().apply { setDataSource(url); prepareAsync(); setOnPreparedListener { it.start() }; setOnCompletionListener { it.release() }; setOnErrorListener { mp, _, _ -> mp.release(); true } } } }